{
  "name": "rf_build_tx_packet_1",
  "confidence": "medium",
  "docstring": "Builds a 28-byte transmit packet record from a fixed RF pattern/template blob and an auxiliary global field into the caller's output buffer cursor, then advances the cursor by the packet size.",
  "subsystem": "rf",
  "var_renames": {
    "a1": "tx_packet_cursor",
    "v1": "pattern_template",
    "v2": "template_flags",
    "v4": "dst_base",
    "v5": "template_read_ptr",
    "v6": "template_byte",
    "v7": "aux_data_ptr",
    "v8": "dst_base",
    "v9": "aux_write_ptr",
    "v10": "aux_write_end",
    "v11": "aux_byte"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "fixed packet header byte 0x2d"
    },
    {
      "offset": 1,
      "meaning": "fixed packet header byte 0x1a"
    },
    {
      "offset": 2,
      "meaning": "2-byte control/flags field copied from template offset 12 with bits 2 and 3 forced set"
    },
    {
      "offset": 4,
      "meaning": "single template byte copied from template offset 14"
    },
    {
      "offset": 5,
      "meaning": "start of copied 16-byte pattern/payload field from template offset 15, with output offsets 15 and 16 subsequently zeroed"
    },
    {
      "offset": 21,
      "meaning": "2-byte field copied from template offset 32"
    },
    {
      "offset": 23,
      "meaning": "4-byte auxiliary field copied from dword_1308D8"
    },
    {
      "offset": 27,
      "meaning": "single trailing byte copied from template offset 40"
    }
  ]
}
